class Worker extends Thread {
  @volatile private var stopping = false      // phase-1 latch
  def shutdown(): Unit = stopping = true      // idempotent

  override def run(): Unit =
    try while (!stopping) handleNext()         // safe points
    finally releaseAndFlush()                  // phase 2 cleanup
}

// controller: w.shutdown(); w.interrupt(); w.join()   // completion

